import SwiftUI

struct ExplorerView:View{
 @EnvironmentObject var work:Workspace
 @State private var selection=Set<String>();@State private var name="Reviewed dataset";@State private var importAll=false
 var body:some View{VStack(alignment:.leading,spacing:12){HStack{Picker("Source",selection:$work.selectedSource){ForEach(work.sources){Text($0.name).tag($0.id)}}.frame(maxWidth:380);Picker("Table",selection:$work.selectedTable){ForEach(work.tables,id:\.tableName){Text($0.tableName).tag($0.tableName)}};TextField("Search this table",text:$work.query).onSubmit{work.offset=0;Task{await work.loadPage()}};Button("Search"){work.offset=0;Task{await work.loadPage()}}};HStack{FieldView(field:Field("table.rows","Rows in table",work.total,meaning:"Live SQLite row count for the selected registered table. This is not an inferred file count.",origin:work.selectedSource+" / "+work.selectedTable));TextField("Dataset name",text:$name).frame(width:200);Button("Import selection"){Task{if let r=await work.request("capture",["source":work.selectedSource,"table":work.selectedTable,"keys":Array(selection),"name":name]){work.selectedRevision=r["id"] as? String ?? "";work.notice="Selected records captured in an immutable dataset revision.";await work.datasets()}}}.disabled(selection.isEmpty);Button("Import table…"){importAll=true}.disabled(work.selectedTable.isEmpty)}
 VSplitView{List(selection:$selection){ForEach(work.rows,id:\.key){row in HStack{Text(String(row.id.prefix(22))).font(.system(.caption,design:.monospaced)).frame(width:160,alignment:.leading);Text(summary(row.value)).font(.caption).lineLimit(2);Spacer();Button{work.explain(Field("record.key","Record identity",row.id,meaning:"Stable identity derived from the registered source, table and primary key.",origin:work.selectedSource+" / "+work.selectedTable),source:"metrics")}label:{Image(systemName:"questionmark.circle")}.buttonStyle(.plain)}.tag(row.key)}}.frame(minHeight:130,idealHeight:180)
 VStack(alignment:.leading,spacing:8){if work.record.isEmpty{ContentUnavailableView("Select a record",systemImage:"tablecells",description:Text("Inspect the actual SQLite row beside its JSONL mirror. Source data stays read-only."))}else{HStack{FieldView(field:Field("record.mirror","JSONL integrity",(work.record["jsonl"] as? [String:Any])?["status"] ?? "unknown",meaning:"The actual JSONL mirror is compared with SQLite. Missing, unavailable and bounded previews are not a match.",origin:work.selectedSource+" / "+work.selectedTable));if work.record["truncated"] as? Bool==true{Label("Bounded preview",systemImage:"ellipsis.rectangle").foregroundStyle(.orange)}};HSplitView{JsonPane(title:"SQLite",value:work.record["sqlite"] ?? [:],source:work.selectedSource+" / "+work.selectedTable);JsonPane(title:"JSONL mirror",value:work.record["jsonl"] ?? [:],source:work.selectedSource+" JSONL")}}}.frame(minHeight:260)}
 HStack{Button("Previous"){work.offset=max(0,work.offset-25);Task{await work.loadPage()}}.disabled(work.offset==0);FieldView(field:Field("table.page","Rows",work.total==0 ? "0 of 0":"\(work.offset+1)–\(min(work.offset+25,work.total)) of \(work.total)",meaning:"Current bounded page of actual SQLite rows. The total is the table count in this observation.",origin:work.selectedSource+" / "+work.selectedTable));Button("Next"){work.offset+=25;Task{await work.loadPage()}}.disabled(work.offset+25>=work.total);Spacer();Text("Tree previews are bounded. Full table imports stream all records locally.").font(.caption).foregroundStyle(.secondary)}
 }.task(id:work.selectedSource){selection=[];await work.loadTables()}.onChange(of:work.selectedTable){_,_ in selection=[];work.offset=0;Task{await work.loadPage()}}.onChange(of:selection){_,keys in if let first=keys.first{Task{await work.loadRecord(first)}}}
 .confirmationDialog("Import every row of \(work.selectedTable) into a new local dataset revision?",isPresented:$importAll){Button("Import table in background"){Task{if let r=await work.request("import-table",["source":work.selectedSource,"table":work.selectedTable,"name":name]){work.notice="Background import \(r["id"] ?? "") started. Track it in Datasets.";await work.datasets()}}}}message:{Text("The source stays read-only. The new revision stores full records and JSONL separately, requiring additional disk space.")}
 }
 func summary(_ values:[String:Any])->String{values.keys.sorted().prefix(4).map{key in let v=values[key]!;return key+": "+String(String(describing:v).prefix(110))}.joined(separator:"  ·  ")}
}
extension Dictionary where Key==String,Value==Any{var tableName:String{self["name"] as? String ?? ""}}
